esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 amount) public payable {
        require(true);
        bool reverted; c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        // In P the caller has deposited nothing, so withdraw only succeeds for amount == 0.
        assert(reverted || amount == 0);
    }
    receive() external payable {}
}

